ImageListItem item = Items[e.Index] as ImageListItem;                Rectangle bounds = e.Bounds;                if (item != null && ImagesList != null) {                    Size imageSize = ImagesList.ImageSize;                    if (item.Index != -1) {                        ImagesList.Draw(e.Graphics, bounds.Left, bounds.Top, item.Index);                        bounds.Offset(                            bounds.Left + imageSize.Width,                             Convert.ToInt32((imageSize.Height - Font.GetHeight()) / 2)                        );                    }                }                if (item != null) {                    e.Graphics.DrawString(                        item.Text,                        e.Font,                        new SolidBrush(e.ForeColor),                        bounds.Left,                        bounds.Top                    );                } else {                    e.Graphics.DrawString(                        Items[e.Index].ToString(),                        e.Font,                        new SolidBrush(e.ForeColor),                        bounds.Left,                        bounds.Top                    );                }